def transform(x):
    """Return the elements of *x* that are at prime (0‑based) indices,
    sorted in non‑decreasing order."""
    def is_prime(n):
        if n < 2:
            return False
        if n % 2 == 0:
            return n == 2
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    # collect elements whose index is prime
    selected = [value for idx, value in enumerate(x) if is_prime(idx)]
    # return them sorted
    return sorted(selected)

